}
.end-row{display:flex;align-items:baseline;gap:10px;padding:4px 0;border-bottom:1px solid rgba(233,221,196,.07);line-height:1.2}
.end-row:last-of-type{border-bottom:0}
.end-row span{flex:0 0 68px;font-size:6px;letter-spacing:.19em;color:var(--paper-faint);text-transform:uppercase}
.end-row b{font-family:var(--serif);font-size:clamp(11px,1.55vh,13px);font-weight:900;color:var(--paper);line-height:1.15}
.screen-end.is-win #endKiller{color:var(--gold-bright)}
.screen-end.is-loss #endKiller{color:#c2a08d}
.end-nail{
  margin-top:7px;padding-top:7px;border-top:1px solid rgba(233,221,196,.12);
