.screen-office.is-answered .call-dot{background:var(--gold-bright);box-shadow:0 0 8px rgba(226,194,134,.65);animation:none}
.call-who{color:var(--paper-bright);letter-spacing:.13em}
.call-live{margin-left:auto;font-size:6.5px;color:var(--gold);border:1px solid rgba(201,161,94,.3);padding:3px 5px}
.screen-office.is-answered .call-live{color:#e2c286;border-color:rgba(226,194,134,.48)}
.call-idle{
  display:flex;align-items:center;gap:10px;margin-top:11px;padding:9px 10px;
