const { chromium } = require('playwright');
const assert = require('assert');
(async()=>{
 const browser=await chromium.launch();
 for(const [w,h] of [[390,844],[360,640],[320,568]]){
  const page=await browser.newPage({viewport:{width:w,height:h},deviceScaleFactor:1});
  const errs=[]; page.on('pageerror',e=>errs.push(String(e)));
  await page.goto('http://localhost:8080/index.html'); await page.waitForTimeout(500);
  assert(await page.isDisabled('#btnGoScene'),'scene button starts disabled');
  assert.equal(await page.getAttribute('#callStatus','id'),null); // noop
  assert.equal(await page.textContent('#callStatus'),'INCOMING');
  assert(await page.isVisible('#phoneHint'));
  assert(await page.isVisible('#phoneZone'));

  // enable sound and confirm ring timer
  await page.click('#soundToggle'); await page.waitForTimeout(250);
  const sound=await page.evaluate(()=>({enabled:__midnight.Sfx.enabled,ctx:__midnight.Sfx.ctx?.state,timer:!!__midnight.Sfx.ringTimer,btn:document.querySelector('#soundToggle').textContent.trim()}));
  console.log('SOUND',w+'x'+h,JSON.stringify(sound));
  assert(sound.enabled); assert(sound.timer); assert(sound.ctx==='running');

  // answer
  await page.click('#phoneZone'); await page.waitForTimeout(700);
  const answered=await page.evaluate(()=>({
    answered:__midnight.state.call.answered, timer:!!__midnight.Sfx.ringTimer, status:document.querySelector('#callStatus').textContent,
    line:document.querySelector('#callLine').textContent, step:document.querySelector('#callStep').textContent,
    hint:getComputedStyle(document.querySelector('#phoneHint')).visibility,
    handset:getComputedStyle(document.querySelector('.phone-handset')).transform,
    sceneDisabled:document.querySelector('#btnGoScene').disabled
  }));
  console.log('ANSWERED',w+'x'+h,JSON.stringify(answered));
  assert(answered.answered); assert(!answered.timer); assert.equal(answered.status,'CONNECTED');
  assert(answered.line.length>20); assert.equal(answered.step,'LINE 1 / 3'); assert.equal(answered.hint,'hidden'); assert(answered.sceneDisabled);
  assert(answered.handset!=='none');

  // advance two more lines then finish
  await page.click('#btnCallNext'); await page.waitForTimeout(250);
  assert.equal(await page.textContent('#callStep'),'LINE 2 / 3');
  await page.click('#btnCallNext'); await page.waitForTimeout(250);
  assert.equal(await page.textContent('#callStep'),'LINE 3 / 3');
  assert((await page.textContent('#btnCallNext')).includes('TAKE THE ADDRESS'));
  await page.click('#btnCallNext'); await page.waitForTimeout(600);
  const done=await page.evaluate(()=>({
    done:__midnight.state.call.done,status:document.querySelector('#callStatus').textContent,
    address:getComputedStyle(document.querySelector('#callAddress')).display,
    addressText:document.querySelector('#officeAddress').textContent,
    sceneDisabled:document.querySelector('#btnGoScene').disabled,
    label:document.querySelector('#btnSceneLabel').textContent
  }));
  console.log('DONE',w+'x'+h,JSON.stringify(done));
  assert(done.done); assert.equal(done.status,'LINE SECURED'); assert.equal(done.address,'flex'); assert(done.addressText.length>2); assert(!done.sceneDisabled); assert.equal(done.label,'HEAD TO THE CRIME SCENE');
  await page.screenshot({path:`/tmp/opencode/shots/office-new-final-${w}x${h}.png`});

  // go to scene
  await page.click('#btnGoScene'); await page.waitForTimeout(700);
  assert.equal(await page.evaluate(()=>__midnight.state.screen),'scene');
  assert(await page.isVisible('#screen-scene'));

  // new case resets phone flow (simulate via button path after startCase)
  await page.evaluate(()=>__midnight.startCase()); await page.waitForTimeout(600);
  const reset=await page.evaluate(()=>({
    answered:__midnight.state.call.answered,done:__midnight.state.call.done,status:document.querySelector('#callStatus').textContent,
    disabled:document.querySelector('#btnGoScene').disabled,label:document.querySelector('#btnSceneLabel').textContent,
    ringing:document.querySelector('#screen-office').classList.contains('is-ringing'),
    dialog:getComputedStyle(document.querySelector('#callDialogue')).display
  }));
  console.log('RESET',w+'x'+h,JSON.stringify(reset));
  assert(!reset.answered&&!reset.done); assert.equal(reset.status,'INCOMING'); assert(reset.disabled); assert.equal(reset.label,'ANSWER THE PHONE'); assert(reset.ringing); assert.equal(reset.dialog,'none');
  if(errs.length) console.log('ERRORS',errs);
  assert.equal(errs.length,0);
  await page.close();
 }
 await browser.close();
 console.log('ALL OFFICE/CALL CHECKS PASSED');
})().catch(e=>{console.error(e);process.exit(1)});
EOF
