content.text:
Now remove RED_PLACES (unused) to avoid confusion? It's fine but lint no matter. Leave.

Now update setCaseChrome/renderCase for scene render & hotspots. Current setCaseChrome last line `$('#sceneArt').dataset.place = c.location.place;` must be removed (location.place undefined). Replace with nothing. We'll render in renderCase.

`renderCase()`:
```
setCaseChrome();
$('#sceneCanvas').innerHTML = renderScene(c.location);
$$('.hotspot').forEach(btn => {
  const key=...
  const meta=stationOf(c.location,key);
  const pt=getStationPoint(c.location,key);
  btn.style.left=pt.x+'%'; btn.style.top=pt.y+'%';
  btn.dataset.side = pt.y > 56 ? 'top' : 'bottom';
  btn.querySelector('.tag').textContent = meta.label;
});
```
But renderCase doesn't declare c; setCaseChrome gets state.caseData. Add `const c = state.caseData;` at start.

`renderSceneState` use meta.label and meta.name.

`renderZoom` use meta:
```
const meta=stationOf(c.location,key);
...
`EXHIBIT ${obj.exhibit} · ${meta.label}`
...
$('#zoomObject').textContent = meta.label;
...
aria-label `Close-up of ${meta.name}`
```

`renderBoard` label meta in two places.

Also hotspot aria label at initial HTML static; renderCase should set it via renderSceneState perhaps. `renderCase` calls `renderBoard` and sets tags; call `renderSceneState()` at end? It currently duplicates logic. Could simply set tags and labels then renderBoard. renderSceneState also updates clueProgress. We can call `renderSceneState()` after setting positions (state.found empty at startCase). But renderCase is called before state.found? startCase sets found then renderCase. Good. Use `renderCase` to set positions + then renderSceneState(); remove manual tag loop. But found set may not be empty if renderCase called later? Only startCase. Fine.

Let's implement.

Also `renderScene` should be called each new case. InnerHTML parsing of SVG in a div works (HTML parser handles svg). Yes.

Now `setCaseChrome` also sets `#sceneArt.dataset.place`; remove. We can set `dataset.scene = c.location.scene` if useful.

Let's edit.

input.newString:
  $('#accuseVictim').textContent = c.victim.name;
  $('#accuseScene').textContent = c.location.name;
}

function renderCase() {
  const c = state.caseData;
  setCaseChrome();
  $('#sceneCanvas').innerHTML = renderScene(c.location);
  $$('.hotspot').forEach((btn) => {
    const key = btn.dataset.object;
    const pt = getStationPoint(c.location, key);
    const meta = stationOf(c.location, key);
    btn.style.left = `${pt.x}%`;
    btn.style.top = `${pt.y}%`;
    btn.dataset.side = pt.y > 56 ? 'top' : 'bottom';
    btn.querySelector('.tag').textContent = meta.label;
    btn.setAttribute('aria-label', `Inspect ${meta.name}`);
  });
  $('#clueProgress').textContent = '0 OF 4 CLUES LOGGED';
  renderSceneState();
  renderBoard();
}

function renderSceneState() {
  const c = state.caseData;
  $$('.hotspot').forEach((btn) => {
    const key = btn.dataset.object;
    const found = state.found.has(key);
    const meta = stationOf(c.location, key);
    btn.classList.toggle('found', found);
    btn.querySelector('.tag').textContent = found ? `${meta.label} ✓` : meta.label;
    btn.setAttribute('aria-label', `${found ? 'Review' : 'Inspect'} ${meta.name}`);
  });
  $('#clueProgress').textContent = `${state.found.size} OF 4 CLUES LOGGED`;
}

function renderZoom() {
  const c = state.caseData;
  const key = state.currentObject || 'desk';
  const obj = OBJECTS[key];
  const meta = stationOf(c.location, key);
  const clue = c.clues[key];
  $('#zoomCanvas').innerHTML = CLOSEUPS[key];
  $('#zoomArt').dataset.object = key;
  $('#zoomExhibit').textContent = `EXHIBIT ${obj.exhibit} · ${meta.label}`;
  $('#zoomPlate').textContent = `PLATE ${obj.plate}`;
  $('#zoomClueNo').textContent = `CLUE ${OBJECT_ORDER.indexOf(key) + 1} / 04`;
  $('#zoomObject').textContent = meta.label;
  $('#clueText').textContent = clue.text;
  $('#clueSheet').classList.toggle('is-gun', clue.type === 'gun');
  $('#zoomFound').textContent = `${state.found.size} / 4`;
  $('#zoomArt').setAttribute('aria-label', `Close-up of ${meta.name}`);
}

function renderBoard() {
  const c = state.caseData;
  if (!c) return;
  $('#boardClueCount').textContent = `${state.found.size} / 4`;
  const tilts = [-0.45, 0.3, -0.18, 0.5];
  const clueHTML = OBJECT_ORDER.map((key, i) => {
    const obj = OBJECTS[key];
    const meta = stationOf(c.location, key);
    const clue = c.clues[key];
    const found = state.found.has(key);
    if (!found) {
      return `<div class="clue-row locked" style="--i:${i};--tilt:${tilts[i]}deg">
        <span class="num">0${i + 1}</span>
        <div class="clue-body">
          <div class="clue-meta-mini"><b>${meta.label}</b><span>SEALED</span></div>
          <div class="clue-txt">NOT YET LOGGED</div>
        </div>
      </div>`;
    }
    return `<div class="clue-row ${clue.type === 'gun' ? 'is-gun' : ''}" style="--i:${i};--tilt:${tilts[i]}deg">
      <span class="num">0${i + 1}</span>
      <div class="clue-body">
        <div class="clue-meta-mini"><b>${meta.label}</b><span>CLUE 0${i + 1}</span><span class="gun-flag">SMOKING GUN</span></div>
        <div class="clue-txt">${esc(clue.text)}</div>
      </div>
    </div>`;
  }).join('');

