import { createRequire } from 'node:module';
import { mkdirSync } from 'node:fs';
import { join } from 'node:path';

const runtime = join(process.env.HOME, '.local/share/omgithub-playwright');
const require = createRequire(join(runtime, 'package.json'));
const { chromium } = require('playwright');

const out = '/tmp/opencode/shots/all';
mkdirSync(out, { recursive: true });

const browser = await chromium.launch({ headless: true });
const page = await browser.newPage({ viewport: { width: 390, height: 844 } });
const errors = [];
page.on('pageerror', (e) => errors.push(e.message));
await page.goto('http://127.0.0.1:4173/index.html', { waitUntil: 'load' });
await page.waitForTimeout(300);

const count = await page.evaluate(() => LOCATIONS.length);
const report = [];

for (let i = 0; i < count; i++) {
  const info = await page.evaluate((idx) => {
    const all = LOCATIONS.slice();
    const target = all[idx];
    previousLocation = null;
    LOCATIONS.length = 0;
    LOCATIONS.push(target);
    state.caseData = makeCase();
    LOCATIONS.length = 0;
    LOCATIONS.push(...all);
    state.found = new Set();
    state.currentObject = null;
    renderCase();
    showScreen('scene');
    const art = document.querySelector('#sceneArt').getBoundingClientRect();
    const tags = [...document.querySelectorAll('.hotspot .tag')].map((t) => {
      const r = t.getBoundingClientRect();
      return { text: t.textContent, x: r.x - art.x, y: r.y - art.y, w: r.width, h: r.height, right: r.right - art.x, bottom: r.bottom - art.y };
    });
    const overlaps = [];
    for (let a = 0; a < tags.length; a++) for (let b = a + 1; b < tags.length; b++) {
      const A = tags[a], B = tags[b];
      if (A.x < B.right && B.x < A.right && A.y < B.bottom && B.y < A.bottom) overlaps.push(`${A.text}/${B.text}`);
    }
    const outside = tags.filter((t) => t.x < 0 || t.y < 0 || t.right > art.width || t.bottom > art.height).map((t) => t.text);
    return {
      idx, scene: target.scene, name: target.name, plate: target.plate,
      tagCount: tags.length, overlaps, outside,
      scrollW: document.documentElement.scrollWidth, scrollH: document.documentElement.scrollHeight,
      clue0: state.caseData.clues.desk.text
    };
  }, i);
  report.push(info);
  await page.waitForTimeout(120);
  await page.locator('#sceneArt').screenshot({ path: join(out, `${String(i + 1).padStart(2, '0')}-${info.scene}.png`) });
}

console.log(JSON.stringify(report, null, 1));
console.log('PAGE ERRORS', errors);
await browser.close();

