import { createRequire } from 'node:module';
import { mkdirSync } from 'node:fs';
import { join } from 'node:path';

const runtime = join(process.env.HOME, '.local/share/omgithub-playwright');
const require = createRequire(join(runtime, 'package.json'));
const { chromium } = require('playwright');

const out = '/tmp/opencode/shots/flow';
mkdirSync(out, { recursive: true });
const browser = await chromium.launch({ headless: true });
const sizes = [
  { w: 390, h: 844, tag: '390x844' },
  { w: 360, h: 640, tag: '360x640' },
  { w: 320, h: 568, tag: '320x568' }
];
const results = [];
const fail = (msg) => { results.push('FAIL: ' + msg); };
const pass = (msg) => { results.push('ok: ' + msg); };

for (const size of sizes) {
  const page = await browser.newPage({ viewport: { width: size.w, height: size.h } });
  const errors = [];
  page.on('pageerror', (e) => errors.push('PAGEERROR ' + e.message));
  page.on('console', (m) => { if (m.type() === 'error') errors.push('CONSOLE ' + m.text()); });
  await page.goto('http://127.0.0.1:4173/index.html', { waitUntil: 'load' });
  await page.waitForTimeout(500);

  const metrics = () => page.evaluate(() => ({
    screen: state.screen,
    scrollW: document.documentElement.scrollWidth,
    clientW: document.documentElement.clientWidth,
    scrollH: document.documentElement.scrollHeight,
    clientH: document.documentElement.clientHeight,
    bodyH: document.body.scrollHeight,
    appH: document.querySelector('#app').scrollHeight
  }));
  const noScroll = async (label) => {
    const m = await metrics();
    const okW = m.scrollW <= m.clientW + 1;
    const okH = m.scrollH <= m.clientH + 1;
    if (okW && okH) pass(`${size.tag} ${label} no scroll (${m.scrollW}x${m.scrollH})`);
    else fail(`${size.tag} ${label} scroll ${m.scrollW}x${m.scrollH} vs ${m.clientW}x${m.clientH}`);
  };

  /* ---- office / call ---- */
  await noScroll('office');
  const office = await page.evaluate(() => ({
    ringing: document.querySelector('#screen-office').classList.contains('is-ringing'),
    status: document.querySelector('#callStatus').textContent,
    btnDisabled: document.querySelector('#btnGoScene').disabled,
    address: state.caseData.location.address,
    scene: state.caseData.location.scene
  }));
  if (office.ringing && office.status === 'INCOMING' && office.btnDisabled) pass(`${size.tag} office starts ringing, scene locked`);
  else fail(`${size.tag} office initial state ${JSON.stringify(office)}`);

  await page.click('#phoneZone');
  await page.waitForTimeout(180);
  for (let i = 0; i < 4; i++) {
    const done = await page.evaluate(() => state.call.done);
    if (done) break;
    await page.click('#btnCallNext');
    await page.waitForTimeout(150);
  }
  const call = await page.evaluate(() => ({
    done: state.call.done,
    status: document.querySelector('#callStatus').textContent,
    btnLabel: document.querySelector('#btnSceneLabel').textContent,
    sub: document.querySelector('#officeSub').textContent,
    wrongAddress: !document.querySelector('#officeSub').textContent.includes(state.caseData.location.plate[1])
  }));
  if (call.done && call.status === 'LINE SECURED' && call.btnLabel.includes('HEAD TO')) pass(`${size.tag} call completes -> address`);
  else fail(`${size.tag} call completion ${JSON.stringify(call)}`);
  await noScroll('office answered');
  if (size.tag === '390x844') await page.screenshot({ path: join(out, `${size.tag}-office.png`) });

  await page.click('#btnGoScene');
  await page.waitForTimeout(900);
  await noScroll('scene');

  /* ---- scene + hotspots + sign ---- */
  const scene = await page.evaluate(() => {
    const c = state.caseData;
    const meta = (k) => getStationMeta(c.location, k);
    const box = document.querySelector('#sceneArt').getBoundingClientRect();
    const tags = [...document.querySelectorAll('.hotspot')].map((b) => {
      const r = b.querySelector('.tag').getBoundingClientRect();
      return { key: b.dataset.object, text: b.querySelector('.tag').textContent, label: meta(b.dataset.object).label,
        left: r.left, top: r.top, right: r.right, bottom: r.bottom };
    });
    const overlaps = [];
    for (let i = 0; i < tags.length; i++) for (let j = i + 1; j < tags.length; j++) {
      const a = tags[i], b = tags[j];
      if (a.left < b.right && b.left < a.right && a.top < b.bottom && b.top < a.bottom) overlaps.push([a.key, b.key]);
    }
    const outside = tags.filter((t) => t.left < box.left - 1 || t.right > box.right + 1 || t.top < box.top - 1 || t.bottom > box.bottom + 1).map((t) => t.key);
    const svg = document.querySelector('#sceneCanvas svg');
    const svgText = svg?.textContent || '';
    const plate = c.location.plate || [];
    return {
      scene: c.location.scene, name: c.location.name, tags,
      overlaps, outside,
      signTop: plate[0], signMain: plate[1],
      hasTop: svgText.includes(plate[0]), hasMain: svgText.includes(plate[1]),
      svg: !!svg,
      hotspots: document.querySelectorAll('.hotspot').length
    };
  });
  if (scene.svg && scene.hotspots === 4) pass(`${size.tag} scene ${scene.scene} renders 4 hotspots`);
  else fail(`${size.tag} scene render ${JSON.stringify({ svg: scene.svg, hotspots: scene.hotspots })}`);
  if (scene.tags.every((t) => t.text === t.label)) pass(`${size.tag} hotspot labels match station meta`);
  else fail(`${size.tag} hotspot label mismatch ${JSON.stringify(scene.tags)}`);
  if (!scene.overlaps.length) pass(`${size.tag} no hotspot tag overlaps`);
  else fail(`${size.tag} tag overlaps ${JSON.stringify(scene.overlaps)}`);
  if (!scene.outside.length) pass(`${size.tag} tags inside scene`);
  else fail(`${size.tag} tags outside scene ${JSON.stringify(scene.outside)}`);
  if (scene.hasTop && scene.hasMain) pass(`${size.tag} address "${scene.signTop} ${scene.signMain}" present in scene art`);
  else fail(`${size.tag} address missing in scene art (${scene.signTop}/${scene.signMain}) ${JSON.stringify({ hasTop: scene.hasTop, hasMain: scene.hasMain })}`);
  if (size.tag === '390x844') await page.screenshot({ path: join(out, `${size.tag}-scene.png`) });

  /* ---- open all four ---- */
  for (const key of ['desk', 'window', 'coat', 'safe']) {
    await page.evaluate((k) => openObject(k), key);
    await page.waitForTimeout(280);
    const z = await page.evaluate((k) => {
      const meta = getStationMeta(state.caseData.location, k);
      const clue = state.caseData.clues[k];
      return {
        screen: state.screen,
        label: document.querySelector('#zoomExhibit').textContent,
        object: document.querySelector('#zoomObject').textContent,
        plate: document.querySelector('#zoomPlate').textContent,
        clue: document.querySelector('#zoomClue').textContent,
        expectedLabel: meta.label, expectedClue: clue.text, expectedPlate: OBJECTS[k].plate
      };
    }, key);
    const ok = z.screen === 'zoom' && z.label.includes(z.expectedLabel) && z.plate.includes(z.expectedPlate)
      && z.object === z.expectedLabel && z.clue === z.expectedClue;
    if (ok) pass(`${size.tag} zoom ${key} label/plate/clue`);
    else fail(`${size.tag} zoom ${key} ${JSON.stringify(z)}`);
    if (key === 'desk' && size.tag === '390x844') await page.screenshot({ path: join(out, `${size.tag}-zoom.png`) });
    await noScroll(`zoom ${key}`);
    await page.evaluate(() => goScene());
    await page.waitForTimeout(180);
  }
  const logged = await page.evaluate(() => ({
    progress: document.querySelector('#clueProgress').textContent,
    found: state.found.size
  }));
  if (logged.found === 4 && logged.progress.startsWith('4 OF 4')) pass(`${size.tag} four clues logged`);
  else fail(`${size.tag} clue progress ${JSON.stringify(logged)}`);

  /* ---- board ---- */
  await page.evaluate(() => goBoard());
  await page.waitForTimeout(720);
  await noScroll('board');
  const board = await page.evaluate(() => {
    const c = state.caseData;
    const labels = [...document.querySelectorAll('#clueList .clue-meta-mini b')].map((b) => b.textContent);
    const expected = ['desk', 'window', 'coat', 'safe'].map((k) => getStationMeta(c.location, k).label);
    const strings = document.querySelectorAll('#boardStrings path').length;
    const boardBody = document.querySelector('.board-body');
    const inner = boardBody ? { scrollH: boardBody.scrollHeight, clientH: boardBody.clientHeight, scrollW: boardBody.scrollWidth, clientW: boardBody.clientWidth } : null;
    return { labels, expected, strings, gunFlags: document.querySelectorAll('.gun-flag').length, clueRows: document.querySelectorAll('.clue-row').length, inner };
  });
  if (board.clueRows === 4 && board.labels.every((l, i) => l === board.expected[i])) pass(`${size.tag} board clue labels match scene stations`);
  else fail(`${size.tag} board labels ${JSON.stringify(board)}`);
  if (board.strings === 3 && board.gunFlags === 1) pass(`${size.tag} board draws 3 strings + smoking gun flag`);
  else fail(`${size.tag} board strings/flags ${JSON.stringify({ strings: board.strings, gun: board.gunFlags })}`);
  if (size.tag === '390x844') await page.screenshot({ path: join(out, `${size.tag}-board.png`) });

  /* ---- accuse screen + wrong accusation (loss) ---- */
  const killer = await page.evaluate(() => state.caseData.killerIndex);
  await page.click('#btnAccuse');
  await page.waitForTimeout(300);
  await noScroll('accuse');
  const acc = await page.evaluate(() => ({
    rows: document.querySelectorAll('.accuse-row').length,
    warning: document.querySelector('#accuseWarning')?.textContent || document.querySelector('.accuse-warn')?.textContent || '',
    safe: !!document.querySelector('.accuse-warn.safe, #accuseWarning.safe'),
    btnDisabled: document.querySelector('#btnMakeAccusation').disabled
  }));
  if (acc.rows === 3 && acc.btnDisabled) pass(`${size.tag} accuse lists 3 suspects`);
  else fail(`${size.tag} accuse screen ${JSON.stringify(acc)}`);
  if (acc.safe) pass(`${size.tag} accuse shows smoking-gun safe state`);
  else fail(`${size.tag} accuse warning not safe: ${JSON.stringify(acc)}`);
  if (size.tag === '390x844') await page.screenshot({ path: join(out, `${size.tag}-accuse.png`) });
  const wrong = (killer + 1) % 3;
  await page.evaluate((i) => selectSuspect(i), wrong);
  await page.click('#btnMakeAccusation');
  await page.waitForTimeout(150);
  await page.click('#btnDoAccuse');
  await page.waitForTimeout(900);
  await noScroll('end loss');
  const loss = await page.evaluate(() => ({
    screen: state.screen,
    stamp: document.querySelector('#endStamp').textContent,
    copy: document.querySelector('#endCopy').textContent,
    killer: document.querySelector('#endKiller').textContent,
    trueKiller: state.caseData.suspects[state.caseData.killerIndex].name,
    failure: state.failure
  }));
  if (loss.screen === 'end' && loss.stamp === 'CASE COLD' && loss.failure === 'wrong' && loss.killer === loss.trueKiller) pass(`${size.tag} wrong accusation -> CASE COLD reveals true killer`);
  else fail(`${size.tag} wrong accusation ${JSON.stringify(loss)}`);
  if (size.tag === '390x844') await page.screenshot({ path: join(out, `${size.tag}-loss.png`) });

  /* ---- new case resets call ---- */
  const oldScene = scene.scene;
  await page.click('#btnNewCase');
  await page.waitForTimeout(600);
  await noScroll('office reset');
  const reset = await page.evaluate(() => ({
    screen: state.screen,
    ringing: document.querySelector('#screen-office').classList.contains('is-ringing'),
    status: document.querySelector('#callStatus').textContent,
    btnDisabled: document.querySelector('#btnGoScene').disabled,
    answered: state.call.answered,
    line: document.querySelector('#callLine').textContent,
    scene: state.caseData.location.scene,
    found: state.found.size
  }));
  if (reset.screen === 'office' && reset.ringing && reset.status === 'INCOMING' && reset.btnDisabled && !reset.answered && reset.line === '' && reset.found === 0) pass(`${size.tag} new case resets call + board`);
  else fail(`${size.tag} reset ${JSON.stringify(reset)}`);
  if (reset.scene !== oldScene) pass(`${size.tag} new case moved from ${oldScene} to ${reset.scene}`);
  else fail(`${size.tag} new case reused scene ${oldScene}`);

  /* ---- win path ---- */
  await page.evaluate(() => { answerPhone(); });
  await page.waitForTimeout(120);
  await page.evaluate(() => { advanceCall(); advanceCall(); advanceCall(); });
  await page.waitForTimeout(200);
  await page.evaluate(() => {
    goScene();
    ['desk', 'window', 'coat', 'safe'].forEach((k) => state.found.add(k));
    renderSceneState();
    goBoard();
  });
  await page.waitForTimeout(500);
  const winKiller = await page.evaluate(() => state.caseData.killerIndex);
  await page.evaluate((i) => { accuseIndex(i); }, winKiller);
  await page.waitForTimeout(1000);
  await noScroll('end win');
  const win = await page.evaluate(() => ({
    screen: state.screen,
    stamp: document.querySelector('#endStamp').textContent,
    headline: document.querySelector('#endHeadline').textContent,
    copy: document.querySelector('#endCopy').textContent,
    label: document.querySelector('#endKillerLabel').textContent,
    killer: document.querySelector('#endKiller').textContent,
    trueKiller: state.caseData.suspects[state.caseData.killerIndex].name,
    failure: state.failure
  }));
  if (win.screen === 'end' && win.stamp === 'CASE CLOSED' && win.label === 'ARRESTED' && win.killer === win.trueKiller && win.failure === null) pass(`${size.tag} correct + smoking gun -> CASE CLOSED`);
  else fail(`${size.tag} win ${JSON.stringify(win)}`);
  if (size.tag === '390x844') await page.screenshot({ path: join(out, `${size.tag}-win.png`) });

  /* ---- no-gun path ---- */
  await page.click('#btnNewCase');
  await page.waitForTimeout(500);
  await page.evaluate(() => { answerPhone(); advanceCall(); advanceCall(); advanceCall(); });
  await page.waitForTimeout(150);
  await page.evaluate(() => { goScene(); goBoard(); });
  await page.waitForTimeout(400);
  const noGunKiller = await page.evaluate(() => state.caseData.killerIndex);
  await page.evaluate((i) => { accuseIndex(i); }, noGunKiller);
  await page.waitForTimeout(1000);
  const noGun = await page.evaluate(() => ({
    screen: state.screen,
    stamp: document.querySelector('#endStamp').textContent,
    copy: document.querySelector('#endCopy').textContent,
    failure: state.failure,
    clueCount: document.querySelector('#endNail')?.textContent?.length || 0
  }));
  if (noGun.screen === 'end' && noGun.stamp === 'CASE COLD' && noGun.failure === 'no-gun' && /right name and empty hands/.test(noGun.copy)) pass(`${size.tag} correct without gun -> right name, empty hands`);
  else fail(`${size.tag} no-gun ${JSON.stringify(noGun)}`);

  /* ---- location rotation sanity ---- */
  const rotation = await page.evaluate(() => {
    const names = [];
    for (let i = 0; i < 40; i++) names.push(makeCase().location.name);
    const repeats = names.filter((n, i) => i > 0 && n === names[i - 1]);
    return { unique: new Set(names).size, repeats: repeats.length };
  });
  if (!rotation.repeats) pass(`${size.tag} 40 cases never repeat consecutive location (${rotation.unique} distinct)`);
  else fail(`${size.tag} location repeats ${rotation.repeats}`);

  if (errors.length) fail(`${size.tag} page errors ${JSON.stringify(errors)}`);
  else pass(`${size.tag} no console/page errors`);
  await page.close();
}

console.log(results.join('\n'));
const fails = results.filter((r) => r.startsWith('FAIL'));
console.log(`\nSUMMARY: ${results.length - fails.length} passed, ${fails.length} failed`);
await browser.close();
process.exit(fails.length ? 1 : 0);

