import { createRequire } from 'node:module';
import { mkdirSync } from 'node:fs';
import { join } from 'node:path';

const runtime = join(process.env.HOME, '.local/share/omgithub-playwright');
const require = createRequire(join(runtime, 'package.json'));
const { chromium } = require('playwright');

const out = '/tmp/opencode/shots/flow';
mkdirSync(out, { recursive: true });
const browser = await chromium.launch({ headless: true });
const sizes = [
  { w: 390, h: 844, tag: '390x844' },
  { w: 412, h: 915, tag: '412x915' },
  { w: 375, h: 667, tag: '375x667' },
  { w: 360, h: 640, tag: '360x640' },
  { w: 320, h: 568, tag: '320x568' }
];
const results = [];
const fail = (msg) => { results.push('FAIL: ' + msg); };
const pass = (msg) => { results.push('ok: ' + msg); };

for (const size of sizes) {
  const page = await browser.newPage({ viewport: { width: size.w, height: size.h } });
  const errors = [];
  page.on('pageerror', (e) => errors.push('PAGEERROR ' + e.message));
  page.on('console', (m) => { if (m.type() === 'error') errors.push('CONSOLE ' + m.text()); });
  await page.goto('http://127.0.0.1:4173/index.html', { waitUntil: 'load' });
  await page.waitForTimeout(500);

  const metrics = () => page.evaluate(() => ({
    screen: state.screen,
    scrollW: document.documentElement.scrollWidth,
    clientW: document.documentElement.clientWidth,
    scrollH: document.documentElement.scrollHeight,
    clientH: document.documentElement.clientHeight
  }));
  const noScroll = async (label) => {
    const m = await metrics();
    if (m.scrollW <= m.clientW + 1 && m.scrollH <= m.clientH + 1) pass(`${size.tag} ${label} no scroll (${m.scrollW}x${m.scrollH})`);
    else fail(`${size.tag} ${label} scroll ${m.scrollW}x${m.scrollH} vs ${m.clientW}x${m.clientH}`);
  };

  /* office / call */
  await noScroll('office');
  const office = await page.evaluate(() => ({
    ringing: document.querySelector('#screen-office').classList.contains('is-ringing'),
    status: document.querySelector('#callStatus').textContent,
    btnDisabled: document.querySelector('#btnGoScene').disabled,
    address: state.caseData.location.address,
    scene: state.caseData.location.scene
  }));
  if (office.ringing && office.status === 'INCOMING' && office.btnDisabled) pass(`${size.tag} office rings, scene locked`);
  else fail(`${size.tag} office initial state ${JSON.stringify(office)}`);

  await page.click('#phoneZone');
  await page.waitForTimeout(180);
  for (let i = 0; i < 4; i++) {
    if (await page.evaluate(() => state.call.done)) break;
    await page.click('#btnCallNext');
    await page.waitForTimeout(150);
  }
  const call = await page.evaluate(() => ({
    done: state.call.done,
    status: document.querySelector('#callStatus').textContent,
    btnLabel: document.querySelector('#btnSceneLabel').textContent
  }));
  if (call.done && call.status === 'LINE SECURED' && call.btnLabel.includes('HEAD TO')) pass(`${size.tag} call completes to address`);
  else fail(`${size.tag} call completion ${JSON.stringify(call)}`);
  await noScroll('office answered');

  await page.click('#btnGoScene');
  await page.waitForTimeout(900);
  await noScroll('scene');

  /* scene: signs, hotspots, tags */
  const scene = await page.evaluate(() => {
    const c = state.caseData;
    const meta = (k) => getStationMeta(c.location, k);
    const box = document.querySelector('#sceneArt').getBoundingClientRect();
    const tags = [...document.querySelectorAll('.hotspot')].map((b) => {
      const r = b.querySelector('.tag').getBoundingClientRect();
      return { key: b.dataset.object, text: b.querySelector('.tag').textContent, label: meta(b.dataset.object).label,
        left: r.left, top: r.top, right: r.right, bottom: r.bottom };
    });
    const overlaps = [];
    for (let i = 0; i < tags.length; i++) for (let j = i + 1; j < tags.length; j++) {
      const a = tags[i], b = tags[j];
      if (a.left < b.right && b.left < a.right && a.top < b.bottom && b.top < a.bottom) overlaps.push([a.key, b.key]);
    }
    const outside = tags.filter((t) => t.left < box.left - 1 || t.right > box.right + 1 || t.top < box.top - 1 || t.bottom > box.bottom + 1).map((t) => t.key);
    const svgText = document.querySelector('#sceneCanvas svg')?.textContent || '';
    const [top, main] = c.location.plate || [];
    return { scene: c.location.scene, tags, overlaps, outside, hasTop: svgText.includes(top), hasMain: svgText.includes(main),
      svg: !!document.querySelector('#sceneCanvas svg'), hotspots: document.querySelectorAll('.hotspot').length };
  });
  if (scene.svg && scene.hotspots === 4) pass(`${size.tag} scene ${scene.scene} renders 4 hotspots`);
  else fail(`${size.tag} scene render ${JSON.stringify({ svg: scene.svg, hotspots: scene.hotspots })}`);
  if (scene.tags.every((t) => t.text === t.label)) pass(`${size.tag} hotspot labels match stations`);
  else fail(`${size.tag} hotspot labels ${JSON.stringify(scene.tags)}`);
  if (!scene.overlaps.length) pass(`${size.tag} no hotspot tag overlaps`);
  else fail(`${size.tag} tag overlaps ${JSON.stringify(scene.overlaps)}`);
  if (!scene.outside.length) pass(`${size.tag} tags stay inside scene`);
  else fail(`${size.tag} tags outside ${JSON.stringify(scene.outside)}`);
  if (scene.hasTop && scene.hasMain) pass(`${size.tag} spoken address present in scene`);
  else fail(`${size.tag} address missing in art`);

  /* zoom each clue */
  for (const key of ['desk', 'window', 'coat', 'safe']) {
    await page.evaluate((k) => openObject(k), key);
    await page.waitForTimeout(280);
    const z = await page.evaluate((k) => {
      const meta = getStationMeta(state.caseData.location, k);
      return {
        screen: state.screen,
        label: document.querySelector('#zoomExhibit').textContent,
        object: document.querySelector('#zoomObject').textContent,
        plate: document.querySelector('#zoomPlate').textContent,
        clue: document.querySelector('#clueText').textContent,
        expectedLabel: meta.label, expectedClue: state.caseData.clues[k].text, expectedPlate: OBJECTS[k].plate
      };
    }, key);
    if (z.screen === 'zoom' && z.label.includes(z.expectedLabel) && z.plate.includes(z.expectedPlate) && z.object === z.expectedLabel && z.clue === z.expectedClue)
      pass(`${size.tag} zoom ${key} label/plate/clue`);
    else fail(`${size.tag} zoom ${key} ${JSON.stringify(z)}`);
    await noScroll(`zoom ${key}`);
    await page.evaluate(() => goScene());
    await page.waitForTimeout(160);
  }
  const logged = await page.evaluate(() => ({ progress: document.querySelector('#clueProgress').textContent, found: state.found.size }));
  if (logged.found === 4 && logged.progress.startsWith('4 OF 4')) pass(`${size.tag} four clues logged`);
  else fail(`${size.tag} clue progress ${JSON.stringify(logged)}`);

  /* board */
  await page.evaluate(() => goBoard());
  await page.waitForTimeout(720);
  await noScroll('board');
  const board = await page.evaluate(() => {
    const c = state.caseData;
    const labels = [...document.querySelectorAll('#clueList .clue-meta-mini b')].map((b) => b.textContent);
    const expected = ['desk', 'window', 'coat', 'safe'].map((k) => getStationMeta(c.location, k).label);
    return { labels, expected, strings: document.querySelectorAll('#boardStrings path').length,
      gunFlags: document.querySelectorAll('.clue-row.is-gun .gun-flag').length, rows: document.querySelectorAll('.clue-row').length,
      truncated: [...document.querySelectorAll('#clueList .clue-txt')].filter((el) => el.scrollHeight > el.clientHeight + 1).length };
  });
  if (board.rows === 4 && board.labels.every((l, i) => l === board.expected[i])) pass(`${size.tag} board labels match stations`);
  else fail(`${size.tag} board labels ${JSON.stringify(board)}`);
  if (board.strings === 3 && board.gunFlags === 1) pass(`${size.tag} 3 strings + 1 smoking-gun flag`);
  else fail(`${size.tag} board strings/flags ${JSON.stringify(board)}`);
  if (board.truncated === 0) pass(`${size.tag} no board clue text truncated`);
  else fail(`${size.tag} ${board.truncated} truncated clue rows`);

  /* accuse + wrong accusation */
  const killer = await page.evaluate(() => state.caseData.killerIndex);
  await page.click('#btnAccuse');
  await page.waitForTimeout(300);
  await noScroll('accuse');
  const acc = await page.evaluate(() => ({
    rows: document.querySelectorAll('.accuse-row').length,
    safe: !!document.querySelector('#gunWarning.safe'),
    btnDisabled: document.querySelector('#btnMakeAccusation').disabled
  }));
  if (acc.rows === 3 && acc.btnDisabled && acc.safe) pass(`${size.tag} accuse lists 3 + gun-safe state`);
  else fail(`${size.tag} accuse ${JSON.stringify(acc)}`);
  await page.evaluate((i) => selectSuspect(i), (killer + 1) % 3);
  await page.click('#btnMakeAccusation');
  await page.waitForTimeout(150);
  await page.click('#btnDoAccuse');
  await page.waitForTimeout(900);
  await noScroll('end loss');
  const loss = await page.evaluate(() => ({
    screen: state.screen, stamp: document.querySelector('#endStamp').textContent,
    killer: document.querySelector('#endKiller').textContent,
    trueKiller: state.caseData.suspects[state.caseData.killerIndex].name, failure: state.failure
  }));
  if (loss.screen === 'end' && loss.stamp === 'CASE COLD' && loss.failure === 'wrong' && loss.killer === loss.trueKiller) pass(`${size.tag} wrong accusation -> CASE COLD`);
  else fail(`${size.tag} wrong accusation ${JSON.stringify(loss)}`);

  /* new case reset */
  const oldScene = scene.scene;
  await page.click('#btnNewCase');
  await page.waitForTimeout(600);
  await noScroll('office reset');
  const reset = await page.evaluate(() => ({
    screen: state.screen, ringing: document.querySelector('#screen-office').classList.contains('is-ringing'),
    status: document.querySelector('#callStatus').textContent, btnDisabled: document.querySelector('#btnGoScene').disabled,
    answered: state.call.answered, line: document.querySelector('#callLine').textContent,
    scene: state.caseData.location.scene, found: state.found.size
  }));
  if (reset.screen === 'office' && reset.ringing && reset.status === 'INCOMING' && reset.btnDisabled && !reset.answered && reset.line === '' && reset.found === 0) pass(`${size.tag} new case resets call + board`);
  else fail(`${size.tag} reset ${JSON.stringify(reset)}`);
  if (reset.scene !== oldScene) pass(`${size.tag} new location ${oldScene} -> ${reset.scene}`);
  else fail(`${size.tag} reused scene ${oldScene}`);

  /* win */
  await page.evaluate(() => { answerPhone(); advanceCall(); advanceCall(); advanceCall(); });
  await page.waitForTimeout(200);
  await page.evaluate(() => {
    goScene();
    ['desk', 'window', 'coat', 'safe'].forEach((k) => state.found.add(k));
    renderSceneState(); goBoard();
  });
  await page.waitForTimeout(500);
  const winKiller = await page.evaluate(() => state.caseData.killerIndex);
  await page.evaluate((i) => { window.__midnight.accuseIndex(i); }, winKiller);
  await page.waitForTimeout(1000);
  await noScroll('end win');
  const win = await page.evaluate(() => ({
    screen: state.screen, stamp: document.querySelector('#endStamp').textContent,
    label: document.querySelector('#endKillerLabel').textContent, killer: document.querySelector('#endKiller').textContent,
    trueKiller: state.caseData.suspects[state.caseData.killerIndex].name, failure: state.failure
  }));
  if (win.screen === 'end' && win.stamp === 'CASE CLOSED' && win.label === 'ARRESTED' && win.killer === win.trueKiller && win.failure === null) pass(`${size.tag} correct + gun -> CASE CLOSED`);
  else fail(`${size.tag} win ${JSON.stringify(win)}`);

  /* no gun */
  await page.click('#btnNewCase');
  await page.waitForTimeout(500);
  await page.evaluate(() => { answerPhone(); advanceCall(); advanceCall(); advanceCall(); });
  await page.waitForTimeout(150);
  await page.evaluate(() => { goScene(); goBoard(); });
  await page.waitForTimeout(400);
  const noGunKiller = await page.evaluate(() => state.caseData.killerIndex);
  await page.evaluate((i) => { window.__midnight.accuseIndex(i); }, noGunKiller);
  await page.waitForTimeout(1000);
  const noGun = await page.evaluate(() => ({
    screen: state.screen, stamp: document.querySelector('#endStamp').textContent,
    copy: document.querySelector('#endCopy').textContent, failure: state.failure
  }));
  if (noGun.screen === 'end' && noGun.stamp === 'CASE COLD' && noGun.failure === 'no-gun' && /right name and empty hands/.test(noGun.copy)) pass(`${size.tag} correct without gun -> no-gun loss`);
  else fail(`${size.tag} no-gun ${JSON.stringify(noGun)}`);

  /* rotation */
  const rotation = await page.evaluate(() => {
    const names = [];
    for (let i = 0; i < 40; i++) names.push(makeCase().location.name);
    return { repeats: names.filter((n, i) => i > 0 && n === names[i - 1]).length };
  });
  if (!rotation.repeats) pass(`${size.tag} 40 cases: no consecutive location repeat`);
  else fail(`${size.tag} consecutive repeats ${rotation.repeats}`);

  if (errors.length) fail(`${size.tag} page errors ${JSON.stringify(errors)}`);
  else pass(`${size.tag} no console/page errors`);
  await page.close();
}

console.log(results.join('\n'));
const fails = results.filter((r) => r.startsWith('FAIL'));
console.log(`\nSUMMARY: ${results.length - fails.length} passed, ${fails.length} failed`);
await browser.close();
process.exit(fails.length ? 1 : 0);

import { createRequire } from 'node:module';
import { join } from 'node:path';

const runtime = join(process.env.HOME, '.local/share/omgithub-playwright');
const require = createRequire(join(runtime, 'package.json'));
const { chromium } = require('playwright');

const browser = await chromium.launch({ headless: true });
const page = await browser.newPage({ viewport: { width: 390, height: 844 } });
await page.goto('http://127.0.0.1:4173/index.html', { waitUntil: 'load' });
await page.waitForTimeout(400);

const report = await page.evaluate(() => {
  const problems = [];
  const seenLocations = new Set();
  const seenSuspects = new Set();
  const seenWeapons = new Set();
  const cases = 600;

  for (let n = 0; n < cases; n++) {
    const c = makeCase();
    seenLocations.add(c.location.scene);
    seenWeapons.add(c.weapon);
    const err = (msg) => problems.push(`case ${n} (${c.location.scene}): ${msg}`);

    if (!c.location || !SCENES[c.location.scene]) err('location has no scene');
    if (!c.location.plate || c.location.plate.length !== 2 || c.location.plate.some((p) => !p)) err('bad plate');
    if (!c.location.address || !c.location.feel) err('missing address/feel');
    const spec = SCENES[c.location.scene];
    if (!SCENE_SIGNS[spec.sign?.style]) err('missing/unknown sign style');
    if (!spec.lights || !spec.stations || Object.keys(spec.stations).length !== 4) err('bad scene spec');

    if (!VICTIMS.includes(c.victim)) err('victim not in pool');
    if (!WEAPONS.includes(c.weapon)) err('weapon not in pool');
    if (c.suspects.length !== 3) err('not 3 suspects');
    if (new Set(c.suspects.map((s) => s.name)).size !== 3) err('duplicate suspect names');
    c.suspects.forEach((s) => {
      seenSuspects.add(s.name);
      if (!s.role || !s.motive || !s.alibi) err(`suspect ${s.name} missing role/motive/alibi`);
      if (!s.trace) err(`suspect ${s.name} missing trace`);
      if (!document.querySelector(`#p-${s.portrait}`)) err(`missing portrait ${s.portrait}`);
    });
    if (new Set(c.suspects.map((s) => s.motive)).size !== 3) err('duplicate motives');
    if (new Set(c.suspects.map((s) => s.role)).size !== 3) err('duplicate roles');

    const keys = Object.keys(c.clues).sort();
    if (keys.join(',') !== ['coat', 'desk', 'safe', 'window'].join(',')) err('clue objects wrong');
    const types = Object.values(c.clues).map((cl) => cl.type).sort();
    if (types.join(',') !== ['alibi', 'gun', 'red', 'weapon'].join(',')) err('clue types wrong ' + types.join(','));
    Object.values(c.clues).forEach((cl) => {
      if (typeof cl.text !== 'string' || cl.text.length < 20) err('clue text too short');
      if (cl.object !== Object.keys(c.clues).find((k) => c.clues[k] === cl)) err('clue object mismatch');
    });
    const gun = Object.values(c.clues).find((cl) => cl.type === 'gun');
    if (!gun.text.includes(c.suspects[c.killerIndex].name)) err('gun clue does not name killer');
    if (!['desk', 'window', 'coat', 'safe'].includes(gun.object)) err('gun object invalid');
    if (c.killerIndex !== c.killerIndex || c.killerIndex < 0 || c.killerIndex > 2) err('bad killer index');

    const red = Object.values(c.clues).find((cl) => cl.type === 'red');
    if (!red.text.includes(c.suspects[c.redSuspectIndex].name)) err('red clue does not name red suspect');
    if (c.redSuspectIndex === c.killerIndex) err('red suspect is killer');
    const alibi = Object.values(c.clues).find((cl) => cl.type === 'alibi');
    if (!alibi.text.includes(c.suspects[c.alibiSuspectIndex].name)) err('alibi clue does not name alibi suspect');

    for (const k of ['desk', 'window', 'coat', 'safe']) {
      const meta = getStationMeta(c.location, k);
      if (!meta.label || !meta.name || !meta.place) err(`station meta ${k} incomplete`);
      const pt = getStationPoint(c.location, k);
      if (!Number.isFinite(pt.x) || !Number.isFinite(pt.y) || pt.x <= 0 || pt.x >= 100 || pt.y <= 0 || pt.y >= 100) err(`station point ${k} invalid`);
    }
    const labels = ['desk', 'window', 'coat', 'safe'].map((k) => getStationMeta(c.location, k).label);
    if (new Set(labels).size !== 4) err('duplicate station labels');
  }

  return {
    problems: problems.slice(0, 12),
    problemCount: problems.length,
    cases,
    locationsSeen: seenLocations.size,
    suspectsSeen: seenSuspects.size,
    weaponsSeen: seenWeapons.size,
    totalLocations: Object.keys(SCENES).length,
    totalSuspects: 12,
    totalWeapons: WEAPONS.length
  };
});

console.log(JSON.stringify(report, null, 2));
await browser.close();
process.exit(report.problemCount ? 1 : 0);

import { createRequire } from 'node:module';
import { mkdirSync } from 'node:fs';
import { join } from 'node:path';

const runtime = join(process.env.HOME, '.local/share/omgithub-playwright');
const require = createRequire(join(runtime, 'package.json'));
const { chromium } = require('playwright');

const out = '/tmp/opencode/shots/scenes';
mkdirSync(out, { recursive: true });

const browser = await chromium.launch({ headless: true });
const page = await browser.newPage({ viewport: { width: 390, height: 844 }, deviceScaleFactor: 2 });
const errors = [];
page.on('pageerror', (e) => errors.push('PAGEERROR ' + e.message));
page.on('console', (m) => { if (m.type() === 'error') errors.push('CONSOLE ' + m.text()); });
await page.goto('http://127.0.0.1:4173/index.html', { waitUntil: 'load' });
await page.waitForTimeout(600);

const meta = await page.evaluate(() => {
  const locScenes = LOCATIONS.map((l) => l.scene);
  const specScenes = Object.keys(SCENES);
  return {
    locations: LOCATIONS.length,
    scenes: specScenes.length,
    duplicateLocationScenes: locScenes.filter((s, i) => locScenes.indexOf(s) !== i),
    unusedScenes: specScenes.filter((s) => !locScenes.includes(s)),
    missingScenes: locScenes.filter((s) => !SCENES[s]),
    stationsValid: LOCATIONS.every((l) => ['desk', 'window', 'coat', 'safe'].every((k) => {
      const st = SCENES[l.scene].stations[k];
      return st && STATIONS[st.t];
    }))
  };
});
console.log('spec', JSON.stringify(meta));

const rows = [];
for (let i = 0; i < 24; i++) {
  const info = await page.evaluate((idx) => {
    const all = LOCATIONS.slice();
    const target = all[idx];
    previousLocation = null;
    LOCATIONS.length = 0; LOCATIONS.push(target);
    state.caseData = makeCase();
    LOCATIONS.length = 0; LOCATIONS.push(...all);
    state.found = new Set();
    renderCase();
    showScreen('scene');
    const c = state.caseData;
    const box = document.querySelector('#sceneArt').getBoundingClientRect();
    const tags = [...document.querySelectorAll('.hotspot')].map((b) => {
      const r = b.querySelector('.tag').getBoundingClientRect();
      return { key: b.dataset.object, left: r.left, top: r.top, right: r.right, bottom: r.bottom, text: b.querySelector('.tag').textContent };
    });
    const overlaps = [];
    for (let a = 0; a < tags.length; a++) for (let b = a + 1; b < tags.length; b++) {
      const A = tags[a], B = tags[b];
      if (A.left < B.right && B.left < A.right && A.top < B.bottom && B.top < A.bottom) overlaps.push([A.key, B.key]);
    }
    const outside = tags.filter((t) => t.left < box.left - 1 || t.right > box.right + 1 || t.top < box.top - 1 || t.bottom > box.bottom + 1).map((t) => t.key);
    const svg = document.querySelector('#sceneCanvas svg');
    const text = svg?.textContent || '';
    const [top, main] = c.location.plate;
    return {
      idx, scene: c.location.scene, name: c.location.name, address: c.location.address, plate: `${top} ${main}`,
      hasTop: text.includes(top), hasMain: text.includes(main), svg: !!svg, hotspots: tags.length,
      overlaps, outside, box
    };
  }, i);
  await page.waitForTimeout(1050);
  await page.screenshot({ path: join(out, `${String(i + 1).padStart(2, '0')}-${info.scene}.png`), clip: info.box });
  rows.push(info);
  const bad = !info.svg || info.hotspots !== 4 || !info.hasTop || !info.hasMain || info.overlaps.length || info.outside.length;
  console.log(`${bad ? 'BAD ' : 'OK  '} ${String(i + 1).padStart(2, '0')} ${info.scene.padEnd(12)} ${info.plate.padEnd(20)} tags ${info.hotspots} overlaps ${info.overlaps.length} outside ${info.outside.length}`);
}

const bad = rows.filter((r) => !r.svg || r.hotspots !== 4 || !r.hasTop || !r.hasMain || r.overlaps.length || r.outside.length);
console.log(`\nSUMMARY ${rows.length} scenes, ${bad.length} problems, ${errors.length} page errors`);
if (errors.length) console.log(errors);
await browser.close();
process.exit(bad.length || errors.length ? 1 : 0);

