  .call-line{font-size:10px;margin:7px 0 8px}
  .btn-main{min-height:48px}
  .scene-art{width:min(100%,430px,calc((100cqh - 162px) * .8))}
  .board-victim{display:none}
  .board-body{padding:7px 8px 8px;gap:4px}
  .clue-row{padding:4px 22px 4px 7px;min-height:42px}
