}
@media (max-height:700px){
  .board-notes{display:none}
  .clue-txt{-webkit-line-clamp:3}
  .scene-brief{margin-top:6px;font-size:7.5px;line-height:1.4}
  .accuse-case{display:none}
}
@media (max-height:670px){
  .office-head h1{font-size:30px}
  .office-head .sub{display:none}
  .office-spacer{min-height:38px}
  .call-line{font-size:9.4px}
  .screen-office.is-answered .office-lamp{transform:translateY(-44px) rotate(-1deg)}
  .screen-office.is-answered .phone-zone{transform:translateY(-44px)}
  .call-idle{padding:7px 9px;margin-top:8px}
  .screen-office.is-answered .office-head h1{font-size:28px}
  .scene-progress .tap-hint{display:none}
  .scene-art{width:min(100%,430px,calc((100cqh - 150px) * .8))}
  .clue-txt{-webkit-line-clamp:3;font-size:7.7px}
  .clue-row{padding:3px 20px 3px 6px;min-height:38px}
  .clue-row.locked{min-height:33px}
  .section-head{font-size:6px}
  .suspect-row{padding:3px 5px}
  .mugshot{width:25px;height:34px;flex-basis:25px}
  .sus-name{font-size:11.5px}
  .sus-line{font-size:6.8px}
  .accuse-head h2{font-size:27px}
  .accuse-head p{display:none}
  .accuse-row .mugshot{width:32px;height:43px;flex-basis:32px}
  .accuse-line span{-webkit-line-clamp:1}
  .verdict h2{font-size:27px}
  .verdict p{font-size:9px;margin-top:7px}
  .verdict-figure{margin-top:9px;grid-template-columns:38px minmax(0,1fr);gap:7px;width:min(100%,236px);padding:5px 7px 5px 5px}
  .vf-photo{width:38px;height:48px}
  .vf-tag{font-size:4.9px}
  .vf-text b{font-size:12.5px;margin-top:2px}
  .vf-text i{font-size:6px;margin-top:3px}
  .vf-stamp{font-size:5.8px;padding:2px 3px;bottom:3px;right:5px;letter-spacing:.1em}
  .end-card .end-nail{display:none}
  .end-row{padding:2px 0}
  .clue-text{font-size:10px}
}
@media (max-height:600px){
  .screen-office.is-answered .office-lamp{transform:translateY(-56px) rotate(-1deg)}
  .screen-office.is-answered .phone-zone{transform:translateY(-56px)}
  .screen-office.is-answered .office-head h1{font-size:25px}
  .call-line{font-size:8.8px}
  .call-card{padding:8px 10px 8px}
}
@media (max-width:370px){
  .screen{padding-left:12px;padding-right:12px}
  .hud h2{font-size:18px}
  .office-head h1{font-size:32px}
  .call-address strong{font-size:9px}
  .hotspot .tag{font-size:6px;letter-spacing:.14em}
  .board-actions{grid-template-columns:1fr 1fr}
  .board-actions .btn{font-size:8px;letter-spacing:.09em}
}
@media (prefers-reduced-motion:reduce){
  *,*::before,*::after{animation-duration:.001ms!important;animation-iteration-count:1!important;transition-duration:.001ms!important;scroll-behavior:auto!important}
  .phone-zone{animation:none!important}
  .ring-arcs span,.rain,.grain{animation:none!important}
}

