let zoomTransit = null;

function prefersReducedMotion() {
  return window.matchMedia && window.matchMedia('(prefers-reduced-motion: reduce)').matches;
}

function cancelZoomTransit() {
  if (!zoomTransit) return;
  const { timer, cleanup } = zoomTransit;
  if (timer) clearTimeout(timer);
  if (cleanup) clearTimeout(cleanup);
  zoomTransit = null;
  const transit = $('#zoomTransit');
  const frame = $('#zoomTransitFrame');
  transit.classList.remove('is-on');
  frame.getAnimations().forEach((a) => a.cancel());
  $('.zoom-transit-veil')?.getAnimations().forEach((a) => a.cancel());
  frame.innerHTML = '';
  frame.style.transform = '';
  frame.style.transformOrigin = '';
  frame.style.left = '';
  frame.style.top = '';
  frame.style.width = '';
  frame.style.height = '';
  $('#screen-zoom').classList.remove('is-transit');
}

function beginZoomIn(key, snapshot) {
  const meta = state.zoomMeta;
  if (!meta || !snapshot || prefersReducedMotion() || !snapshot.art.width) {
    $('#screen-zoom').classList.remove('is-transit');
    return;
  }
  const device = $('.device').getBoundingClientRect();
  const bay = $('#zoomArt').getBoundingClientRect();
  if (!bay.width || !bay.height) {
    $('#screen-zoom').classList.remove('is-transit');
    return;
  }

  const transit = $('#zoomTransit');
  const frame = $('#zoomTransitFrame');
  const veil = $('.zoom-transit-veil');
  const left = snapshot.art.left - device.left;
  const top = snapshot.art.top - device.top;
  const originX = (meta.frame.cx / 400) * snapshot.art.width;
  const originY = (meta.frame.cy / 500) * snapshot.art.height;
  const targetX = bay.left - device.left + bay.width / 2;
  const targetY = bay.top - device.top + bay.height / 2;
  const scale = Math.max(1.2, meta.zoom);
  const tx = targetX - (left + originX);
  const ty = targetY - (top + originY);

  frame.innerHTML = snapshot.room;
  frame.style.left = `${left}px`;
  frame.style.top = `${top}px`;
  frame.style.width = `${snapshot.art.width}px`;
  frame.style.height = `${snapshot.art.height}px`;
  frame.style.transformOrigin = `${originX}px ${originY}px`;
  frame.style.transform = 'translate(0px, 0px) scale(1)';
  transit.classList.add('is-on');
  veil.style.opacity = '0';

  const token = Symbol('zoom');
  zoomTransit = { token, timer: 0, cleanup: 0 };
  const ease = 'cubic-bezier(.17,.78,.2,1)';
  frame.animate([
    { transform: 'translate(0px, 0px) scale(1)' },
    { transform: `translate(${tx}px, ${ty}px) scale(${scale})` }
  ], { duration: 640, easing: ease, fill: 'forwards' });
  veil.animate([
    { opacity: 0 },
    { opacity: 0.36, offset: 0.55 },
    { opacity: 0.55 }
  ], { duration: 640, easing: 'ease-in', fill: 'forwards' });

  const finish = () => {
    if (!zoomTransit || zoomTransit.token !== token) return;
    $('#screen-zoom').classList.remove('is-transit');
    frame.animate([{ opacity: 1 }, { opacity: 0 }], { duration: 250, easing: 'ease-out', fill: 'forwards' });
    veil.animate([{ opacity: 0.55 }, { opacity: 0 }], { duration: 280, easing: 'ease-out', fill: 'forwards' });
    zoomTransit.cleanup = setTimeout(() => {
      if (!zoomTransit || zoomTransit.token !== token) return;
      transit.classList.remove('is-on');
      frame.innerHTML = '';
      frame.style.transform = '';
      frame.style.transformOrigin = '';
      frame.style.left = '';
      frame.style.top = '';
      frame.style.width = '';
      frame.style.height = '';
      veil.style.opacity = '0';
      zoomTransit = null;
      cameraFlash(0.45);
    }, 270);
  };
  zoomTransit.timer = setTimeout(finish, 640);
}

function openObject(key) {
  if (state.busy) return;
  state.currentObject = key;
  const isNew = !state.found.has(key);
  state.found.add(key);
  const snapshot = {
    room: $('#sceneCanvas').innerHTML,
    art: $('#sceneArt').getBoundingClientRect()
  };
  $('#screen-zoom').classList.add('is-transit');
  showScreen('zoom');
  beginZoomIn(key, snapshot);
  if (isNew) {
    Sfx.clue();
    announce(`Clue logged: ${state.caseData.clues[key].text}`);
  }
}

