import { createRequire } from 'node:module';
import { join } from 'node:path';

const runtime = join(process.env.HOME, '.local/share/omgithub-playwright');
const require = createRequire(join(runtime, 'package.json'));
const { chromium } = require('playwright');

const browser = await chromium.launch({ headless: true });
const page = await browser.newPage({ viewport: { width: 390, height: 844 } });
const errors = [];
page.on('pageerror', (e) => errors.push('PAGEERROR ' + e.message));
page.on('console', (m) => { if (m.type() === 'error') errors.push('CONSOLE ' + m.text()); });
await page.goto('http://127.0.0.1:4173/index.html', { waitUntil: 'load' });
await page.waitForTimeout(400);

const scenes = await page.evaluate(() => LOCATIONS.map((l) => l.scene));
const bad = [];
let count = 0;
for (const sceneName of scenes) {
  await page.evaluate((s) => {
    const all = LOCATIONS.slice();
    const target = all.find((l) => l.scene === s);
    previousLocation = null;
    LOCATIONS.length = 0;
    LOCATIONS.push(target);
    state.caseData = makeCase();
    LOCATIONS.length = 0;
    LOCATIONS.push(...all);
    state.found = new Set();
    renderCase();
    showScreen('scene');
  }, sceneName);
  await page.waitForTimeout(500);

  for (const key of ['desk', 'window', 'coat', 'safe']) {
    await page.evaluate((k) => openObject(k), key);
    await page.waitForTimeout(1000);
    const r = await page.evaluate((k) => {
      const svg = document.querySelector('#zoomCanvas svg');
      const bay = document.querySelector('#zoomArt').getBoundingClientRect();
      const meta = state.zoomMeta;
      const station = svg?.querySelector(`[data-station="${k}"]`);
      let b = null;
      try { const x = station.getBBox(); b = { x: x.x, y: x.y, w: x.width, h: x.height }; } catch (e) {}
      return {
        bayAr: bay.width / bay.height,
        frameAr: meta.frame.ar,
        frame: { x: meta.frame.x, y: meta.frame.y, w: meta.frame.w, h: meta.frame.h },
        box: b,
        vb: svg?.getAttribute('viewBox'),
        object: document.querySelector('#zoomObject')?.textContent,
        clueLen: document.querySelector('#clueText')?.textContent?.length
      };
    }, key);
    count++;
    const arDiff = Math.abs(r.bayAr - r.frameAr);
    const problems = [];
    if (arDiff > 0.002) problems.push(`bay/frame ar ${r.bayAr.toFixed(4)} vs ${r.frameAr.toFixed(4)}`);
    if (r.box) {
      const pads = {
        l: r.box.x - r.frame.x,
        r: r.frame.x + r.frame.w - (r.box.x + r.box.w),
        t: r.box.y - r.frame.y,
        b: r.frame.y + r.frame.h - (r.box.y + r.box.h)
      };
      if (Math.min(pads.l, pads.r, pads.t, pads.b) < -0.5) problems.push(`clipped ${JSON.stringify(pads)}`);
    } else problems.push('no station bbox');
    if (problems.length) {
      bad.push({ sceneName, key, r, problems });
      console.log('BAD', sceneName, key, r.object, problems.join('; '));
    }
  }
}
console.log(`\nRATIO AUDIT: ${count} close-ups, ${bad.length} bad`);
console.log('errors', errors.length ? errors : 'none');
await browser.close();
process.exitCode = bad.length || errors.length ? 1 : 0;

