import { createRequire } from 'node:module';
import { join } from 'node:path';

const runtime = join(process.env.HOME, '.local/share/omgithub-playwright');
const require = createRequire(join(runtime, 'package.json'));
const { chromium } = require('playwright');

const browser = await chromium.launch({ headless: true });
const page = await browser.newPage({ viewport: { width: 390, height: 844 }, deviceScaleFactor: 2 });
await page.goto('http://127.0.0.1:4173/index.html', { waitUntil: 'load' });
await page.waitForTimeout(500);

const results = [];
for (const sceneName of ['pier9', 'marlowe', 'casino', 'gym', 'radio', 'diner']) {
  await page.evaluate((s) => {
    const all = LOCATIONS.slice();
    const target = all.find((l) => l.scene === s);
    previousLocation = null;
    LOCATIONS.length = 0;
    LOCATIONS.push(target);
    state.caseData = makeCase();
    LOCATIONS.length = 0;
    LOCATIONS.push(...all);
    state.found = new Set();
    renderCase();
    showScreen('scene');
  }, sceneName);
  await page.waitForTimeout(600);

  for (const key of ['desk', 'window', 'coat', 'safe']) {
    await page.evaluate((k) => {
      window.__realSetTimeout = window.setTimeout;
      window.setTimeout = function (fn, ms, ...args) {
        if (ms === 700 || ms === 270) return 0;
        return window.__realSetTimeout(fn, ms, ...args);
      };
      openObject(k);
    }, key);

    const r = await page.evaluate((ms) => {
      const frame = document.querySelector('#zoomTransitFrame');
      const veil = document.querySelector('.zoom-transit-veil');
      [...frame.getAnimations(), ...veil.getAnimations()].forEach((a) => { a.pause(); a.currentTime = ms; });
      const rect = (el) => { const b = el.getBoundingClientRect(); return { x: b.x, y: b.y, w: b.width, h: b.height, cx: b.x + b.width / 2, cy: b.y + b.height / 2 }; };
      const t = frame.querySelector('[data-station]');
      const c = document.querySelector('#zoomCanvas [data-station]');
      const bay = rect(document.querySelector('#zoomCanvas'));
      return { transit: rect(t), closeup: rect(c), bay, meta: state.zoomMeta };
    }, 700);

    const dx = Math.abs(r.transit.cx - r.closeup.cx);
    const dy = Math.abs(r.transit.cy - r.closeup.cy);
    const dw = Math.abs(r.transit.w - r.closeup.w);
    const dh = Math.abs(r.transit.h - r.closeup.h);
    const problems = [];
    if (dx > 1 || dy > 1) problems.push(`center ${dx.toFixed(2)},${dy.toFixed(2)}px`);
    if (dw > 2 || dh > 2) problems.push(`size ${dw.toFixed(2)},${dh.toFixed(2)}px`);
    const targetDx = Math.abs(r.bay.cx - r.closeup.cx);
    const targetDy = Math.abs(r.bay.cy - r.closeup.cy);
    if (targetDx > 1 || targetDy > 1) problems.push(`bay offset ${targetDx.toFixed(2)},${targetDy.toFixed(2)}px`);
    console.log(`${sceneName.padEnd(10)} ${key.padEnd(6)} transit ${r.transit.w.toFixed(1)}x${r.transit.h.toFixed(1)} @ ${r.transit.cx.toFixed(1)},${r.transit.cy.toFixed(1)} | closeup ${r.closeup.w.toFixed(1)}x${r.closeup.h.toFixed(1)} @ ${r.closeup.cx.toFixed(1)},${r.closeup.cy.toFixed(1)} | ${problems.length ? 'BAD ' + problems.join('; ') : 'aligned'}`);
    results.push(problems.length);

    await page.evaluate(() => {
      window.setTimeout = window.__realSetTimeout;
      cancelZoomTransit();
      goScene();
    });
    await page.waitForTimeout(250);
  }
}
console.log(`\nALIGNMENT: ${results.length} checks, ${results.filter(Boolean).length} bad`);
await browser.close();

