import { createRequire } from 'node:module';
import { join } from 'node:path';
const runtime = join(process.env.HOME, '.local/share/omgithub-playwright');
const require = createRequire(join(runtime, 'package.json'));
const { chromium } = require('playwright');
const browser = await chromium.launch({ headless: true });
const page = await browser.newPage({ viewport: { width: 390, height: 844 }, deviceScaleFactor: 2 });
const errors = [];
page.on('pageerror', (e) => errors.push(e.message));
page.on('console', (m) => { if (m.type() === 'error') errors.push(m.text()); });
await page.goto('http://127.0.0.1:4173/index.html', { waitUntil: 'load' });
await page.waitForTimeout(600);
await page.evaluate(() => {
  const all = LOCATIONS.slice();
  const t = all.find((l) => l.scene === 'pier9');
  previousLocation = null;
  LOCATIONS.length = 0; LOCATIONS.push(t);
  state.caseData = makeCase();
  LOCATIONS.length = 0; LOCATIONS.push(...all);
  state.found = new Set();
  renderCase();
  showScreen('scene');
});
await page.waitForTimeout(900);
await page.screenshot({ path: '/tmp/opencode/shots/final-scene.png' });
await page.evaluate(() => openObject('window'));
await page.waitForTimeout(1200);
await page.screenshot({ path: '/tmp/opencode/shots/final-zoom.png' });
console.log(await page.evaluate(() => ({
  screen: state.screen,
  object: document.querySelector('#zoomObject').textContent,
  mag: document.querySelector('#zoomMag').textContent,
  clue: document.querySelector('#clueText').textContent.length,
  scrollY: document.scrollingElement.scrollHeight <= innerHeight,
  errors: 0
})), 'errors', errors.length ? errors : 'none');
await browser.close();
EOF
